func (this *Test_org_eclipse_swt_widgets_Table) Test_Virtual() {
	this.table.Dispose()
	this.table = swt.NewTable(upcastswtShellToswtComposite(this.shell), swt.VIRTUAL|swt.BORDER)
	this.impl.setWidget_(upcastswtTableToswtWidget(this.table))
	var count int32 = 1_000_000
	var visibleCount int32 = 10
	this.shell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
	var dataCounter []int32 = []int32{0}
	this.table.AddListener(swt.SetData, &ListenerFunc{fn: func(event *swt.Event) {
		var item *swt.TableItem = castswtWidgetToswtTableItem(event.Item)
		var index int32 = this.table.IndexOfItem(item)
		item.SetText(fmt.Sprintf("Item %d", index))
		dataCounter[0]++
	}})
	this.shell.SetSize(200, this.table.GetItemHeight()*visibleCount)
	this.shell.Open()
	this.table.SetItemCount(count)
	var end int64 = jrt.CurrentTimeMillis() + 3000
	for !this.shell.IsDisposed() && jrt.CurrentTimeMillis() < end {
		if !this.shell.GetDisplay().ReadAndDispatch() {
			func() {
				defer func() {
					r := recover()
					if r == nil {
						return
					}
					if false {
						var e error
						_ = e
						fmt.Fprintln(os.Stderr, e)
					} else {
						panic(r)
					}
				}()
				jrt.Sleep(int64(10))
			}()
		}
	}
	junit.AssertTrue(dataCounter[0] > visibleCount/2 && dataCounter[0] <= visibleCount*3)
}

func (this *Test_org_eclipse_swt_widgets_Table) Test_setTopIndex() {
	for i := int32(0); i < 10; i++ {
		swt.NewTableItem(this.table, 0)
	}
	for i := int32(0); i < 10; i++ {
		swt.NewTableItem(this.table, 0)
	}
	this.table.SetSize(50, 50)
	this.shell.Open()
	this.table.SetTopIndex(5)
	for i := int32(0); i < 10; i++ {
		swt.NewTableItem(this.table, 0)
	}
	this.shell.SetVisible(false)
	junit.AssertEquals(int32(5), int32(this.table.GetTopIndex()))
}

